        self.assertIn('const SOURCE_OVERDRIVE_PROJECTOR_PLACE_DASH_CIRCLE := "Drawf.dashCircle(x * tilesize + offset, y * tilesize + offset, range, baseColor);"', source)
        self.assertIn('const SOURCE_OVERDRIVE_PROJECTOR_PLACE_EACH_BLOCK := "indexer.eachBlock(player.team(), x * tilesize + offset, y * tilesize + offset, range, other -> other.block.canOverdrive, other -> Drawf.selected(other, Tmp.c1.set(baseColor).a(Mathf.absin(4f, 1f))));"', source)
